% Script to loop through all of the data generated by a study and create 
% the plots that are necessary for tuning stopping criteria, comparing models, etc.

%% Method Comparison Figure
clc; clear; close all;

% Load data
addpath(genpath(fullfile(pwd)))
basepath = "Data/Results/20261104_PriorDataVolume/";
dirnames = dir(basepath+"*sim*");


% yticklocs = [0 1 2 4 5 6 8 9 10 11] ;
