% Load all the data and compute the stopping point
printNumberIGs = cell(length(dirnames),1);
ns = cell(length(dirnames),1);
surf_nums = cell(length(dirnames),1);
surf_letters = cell(length(dirnames),1);
methods = cell(length(dirnames),1);
prior_sizes = zeros(size(printNumberIGs));

for i = 1:size(dirnames,1)
    % Load data
    dirname = basepath + dirnames(i).name;
    fname = dirname + "/" + dirnames(i).name + ".mat";
    load(fname, 'modelPerformance','n','SurfB','method','gprMdls');

    % Error Metrics
    ns{i}=modelPerformance.n;
    [~, printNumberIGs{i}] = MiniCriteria(modelPerformance,0.055);
    
    surf_nums{i} = SurfB(5);
    surf_letters{i} = SurfB(6);
    methods{i} = strcat('M',string(method));
    
    exit=false;
    j=1;
    while ~exit
        if isempty(gprMdls{j})
            j = j+1;
        else
            gprMdl_prior = gprMdls{j};
            exit = true;
        end
    end
    prior_sizes(i) = gprMdl_prior.ActiveSetSize;
    if prior_sizes(i)<2000; prior_sizes(i)=prior_sizes(i)-1;end
    fprintf("completed: %i/%i\n",i,size(dirnames,1))
end

surf_nums = categorical(string(surf_nums));
surf_letters = categorical(upper(surf_letters));
methods = categorical(string(methods));
printNumberIGs = cell2mat(printNumberIGs);

%%
close all
figure(10);
set(gcf, 'Name', 'Method Comparison','WindowStyle', 'normal','Unit','inches','Position',[0 0 3.3 1.5],'Color','white');
hold on
grid on
xticklocs = [0 (4:16).^2];
xticks(xticklocs)
xticklabels([string(xticklocs(1:end-1)) "N/A"])

set(gca,'Clipping','off')
%title('Method Performance Comparison')
xlabel('Number of Points, n*')
ylabel('Prior Data Volume')

all_sizes = unique(prior_sizes);
surfs = string(surf_nums)+string(surf_letters);
all_surfs = unique(surfs);

[all_surfs,all_sizes] = meshgrid(all_surfs,all_sizes);
all_surfs = all_surfs(:); all_sizes = all_sizes(:);

labels = cell(length(all_sizes),1);
failure_rates = zeros(size(labels));
for i=1:length(all_surfs)
    labels{i} = strcat(all_surfs(i),", ",string(all_sizes(i)));
    idxs = (surfs==all_surfs(i)) & (prior_sizes==all_sizes(i));
    nums = printNumberIGs(idxs);
    failure_rates(i) = round(sum(isnan(nums))/length(nums)*100,0);
end

groupingVariables = {surf_nums,surf_letters,prior_sizes};

boxplot(printNumberIGs,groupingVariables,...
    'Orientation','horizontal',...
    'ColorGroup', methods,...
    'Colors',[0.8500 0.3250 0.0980;0.9290 0.6940 0.1250;0.4940 0.1840 0.5560],...
    'PlotStyle','compact',...
    'FactorSeparator',[],...
    'LabelVerbosity','all')

idx_nan = isnan(printNumberIGs);
printNumbers2 = printNumberIGs;
printNumbers2(~idx_nan) = nan;
printNumbers2(idx_nan) = 256;

boxplot(printNumbers2,groupingVariables,...
    'Orientation','horizontal',...
    'ColorGroup', methods,...
    'Colors',[0.8500 0.3250 0.0980;0.9290 0.6940 0.1250;0.4940 0.1840 0.5560],...
    'PlotStyle','compact',...
    'FactorSeparator',[],...
    'FactorGap',[17,7,0],...
    'LabelVerbosity','all')...
    %'Labels',string(labels)')
    

fontsize(6,"points")
xlim([0,225])

saveas(figure(10),'Paper Figures/S1 Prior Data Volume Comparison/FigureS1.fig')
exportgraphics(figure(10),'Paper Figures/S1 Prior Data Volume Comparison/FigureS1.png','Resolution',600)
exportgraphics(figure(10),'Paper Figures/S1 Prior Data Volume Comparison/FigureS1.eps','ContentType','vector')